import json
S = []
def seg(scene, text, kick=None, **params): S.append({"scene": scene, "text": text, "kick": kick, "params": params})
def step(num, title, icon): S.append({"scene": "step", "text": None, "kick": None, "params": {"num": num, "title": title, "icon": icon}, "dur": 3.0})
seg("news", "If you turn on the news today, the message is pretty clear: unless you're earning six figures, winning the lottery, or inheriting a small fortune, buying a house is out of the question.", None, disclaimer=True)
seg("host", "Except... that's not entirely true.", None, mood="smile")
seg("xOverlay", "The problem isn't that you earn a median income. The problem is that most people try to buy a home using rules from twenty years ago.", "THE REAL PROBLEM")
seg("oldRules", "If you save 10% of your paycheck at standard bank rates and wait until you have a 20% cash deposit for a dynamic inner-city property, you will get priced out.", "OLD RULES")
seg("blueprint", "In this video, I'm giving you the exact step-by-step blueprint to go from a median income to holding the keys to your first home, without starving yourself or waiting until you're 60.", "THE BLUEPRINT")
step(1, "FIX YOUR BORROWING CAPACITY FIRST", "card")
seg("borrowBars", "Step one is the biggest secret in real estate: Banks don't care nearly as much about how much you save as they care about your borrowing capacity.", "BORROWING CAPACITY")
seg("cashFlag", "You could have $50,000 sitting in cash, but if the bank's algorithm flags you as high-risk, your pre-approval gets slashed. Here's how you fix that immediately:", "HIGH-RISK FLAG")
seg("creditCard", "Got a credit card with a $10,000 limit that sits in a drawer with zero balance? To a mortgage lender, that's $10,000 of active debt. Closing that card or dropping the limit to $1,000 can instantly boost your borrowing power by $40,000 to $50,000.", "KILL UNUSED CREDIT LIMITS")
seg("debts", "Personal loans, car payments, and Buy-Now-Pay-Later accounts eat your monthly income assessment alive. Pay these off first before putting a single extra dollar into your house deposit.", "ELIMINATE CONSUMER DEBT")
seg("payYourself", "Set up 'Pay Yourself First'. The moment your paycheck lands, automatically shift your target savings percentage straight into a separate account. If you don't see it in your everyday account, you won't spend it.", "AUTOMATE YOUR MONEY")
step(2, "STOP SAVING FOR A 20% DEPOSIT", "piggy")
seg("depositSlow", "Here's where most median-income earners get stuck: trying to save a full 20% deposit. On a median property, 20% plus fees can take 7 to 10 years to save. By the time you get there, house prices have moved further away.", "THE 20% TRAP")
seg("depositTimeline", "Instead, you need to leverage government assistance and modern homebuyer schemes.", "5% vs 20%")
seg("govScheme", "Look into First Home Guarantee programs. In many regions, governments allow first home buyers to purchase with as little as a 5% deposit without paying expensive Lenders Mortgage Insurance.", "LOW-DEPOSIT GOVERNMENT SCHEMES")
seg("taxAccount", "Use tax-effective accounts to build your deposit faster, like the First Home Super Saver scheme in Australia or local equivalents. Saving with pre-tax dollars means growing your deposit up to 30% faster than standard bank savings.", "TAX-ADVANTAGED SAVINGS")
step(3, "THE STEPPING-STONE PROPERTY & RENTVESTING", "house")
seg("splitDream", "Step three requires a mindset shift. Your first home does not have to be your forever home.", "MINDSET SHIFT")
seg("splitDream", "If you try to buy a four-bedroom freestanding house in a top-tier neighborhood as your first move on a median income, you'll get stuck at the starting line. Look at these two strategic entry routes:", "TWO ENTRY ROUTES", mode="stuck")
seg("starter", "Look for well-built townhouses or apartments in emerging outer suburbs or growth corridors. Getting into the market early lets equity build up for 3 to 5 years. You then use that built-up equity as the deposit for your next, bigger property.", "OPTION A: THE STARTER PROPERTY")
seg("rentvest", "Can't afford to buy where you actually want to live? Rent where you love living, and buy an investment property in an affordable, high-growth suburb elsewhere. Your tenant pays down your mortgage while the property gains value.", "OPTION B: RENTVESTING")
step(4, "THE EMERGENCY BUFFER RULE", "shield")
seg("zeroBank", "There's one critical mistake you must avoid: emptying your bank account down to $0 on settlement day.", "DON'T HIT $0")
seg("buffer", "Owning a home comes with unexpected expenses: council rates, building insurance, basic repairs, and interest rate changes. When you calculate your target deposit, ensure you leave a 3-to-6-month emergency buffer untouched. Staying financially secure after you get the keys is just as important as getting them in the first place.", "3-6 MONTH BUFFER")
seg("host", "Buying a home on a median income isn't about luck or waiting for a market crash. It comes down to four clear moves:", "RECAP", mood="smile")
seg("recap", "One. Maximize your borrowing power by clearing credit limits and consumer debt. Two. Target a 5% deposit using government support and tax-advantaged accounts. Three. Buy a starter property or rentvest to get your foot on the property ladder. Four. Keep an emergency safety buffer so you stay secure.", "4 CLEAR MOVES")
seg("ctaYT", "If you found this breakdown helpful, hit that like button, subscribe for more practical finance guides, and drop a comment below letting me know what step you're working on right now. Thanks for watching, and I'll see you in the next video!", None)
S.append({"scene": "endscreen", "text": None, "kick": None, "params": {}, "dur": 12.0})
json.dump(S, open("segments.json", "w"), indent=1)
print(len(S), "segments,", sum(len(s["text"].split()) for s in S if s["text"]), "words")
